  8	public class Application {
  9	    public static void main(String[] args) {
 10	        String dbUrl = System.getenv("DB_URL");
 11	        String dbUser = System.getenv("DB_USER");
 12	        String dbPassword = System.getenv("DB_PASSWORD");
 13	        String portStr = System.getenv("PORT");
 14	
 15	        int port = 7070;
 16	        if (portStr != null && !portStr.isBlank()) {
 17	            try {
 18	                port = Integer.parseInt(portStr);
 19	            } catch (NumberFormatException e) {
 20	                port = 7070;
 21	            }
 22	        }
 23	
 24	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 25	            System.err.println("Environment variables DB_URL, DB_USER, and DB_PASSWORD are required");
 26	            System.exit(1);
 27	        }
 28	
 29	        try {
 30	            Database db = new Database(dbUrl, dbUser, dbPassword);
 31	            db.initialize();
 32	
 33	            ReservationService service = new ReservationService(db);
 34	
 35	            Javalin app = Javalin.create()
 36	                    .start(port);
 37	
 38	            new ReservationAPI(app, service);
 39	
 40	            System.out.println("Pousada Maré Alta running on port " + port);
 41	        } catch (Exception e) {
 42	            System.err.println("Failed to start application: " + e.getMessage());
 43	            e.printStackTrace();
 44	            System.exit(1);
 45	        }
 46	    }
 47	}
 48	package br.com.mareaalta.service;
 49	
 50	import br.com.mareaalta.domain.*;
 51	import br.com.mareaalta.domain.rateplan.*;
 52	import br.com.mareaalta.repository.Database;
 53	import br.com.mareaalta.util.DateUtils;
 54	import br.com.mareaalta.util.Money;
 55	
 56	import java.sql.SQLException;
 57	import java.time.LocalDate;
 58	import java.util.*;
 59	
 60	public class ReservationService {
 61	    private final Database db;
 62	
 63	    public ReservationService(Database db) {
 64	        this.db = db;
 65	    }
 66	
 67	    public Result<Reservation> createReservation(int roomNumber, String guestName, String guestEmail,
 68	                                                   String guestCpf, LocalDate checkIn, LocalDate checkOut,
 69	                                                   int guests, RatePlanType ratePlanType, String companyCode) {
 70	        try {
 71	            Room room = db.getRoomByNumber(roomNumber);
 72	            if (room == null) {
 73	                return Result.error("ROOM_NOT_FOUND", "Quarto não encontrado");
 74	            }
 75	
 76	            RatePlan ratePlan = RatePlanFactory.create(ratePlanType);
 77	            RatePlan.ValidationError validationError = ratePlan.validate(checkIn, checkOut, guests, room, companyCode);
 78	            if (validationError != null) {
 79	                return Result.error(validationError.code(), validationError.message());
 80	            }
 81	
 82	            if (!db.isRoomAvailable(roomNumber, checkIn, checkOut)) {
 83	                return Result.error("ROOM_UNAVAILABLE", "Quarto não disponível para as datas");
 84	            }
 85	
 86	            int nights = DateUtils.nightsBetween(checkIn, checkOut);
 87	
 88	            RatePlan.PricingResult pricing;
 89	            if (ratePlanType == RatePlanType.CORPORATE) {
 90	                CorporateRatePlan corpPlan = (CorporateRatePlan) ratePlan;
 91	                pricing = corpPlan.calculatePriceWithCompany(checkIn, checkOut, room, companyCode);
 92	            } else {
 93	                pricing = ratePlan.calculatePrice(checkIn, checkOut, room);
 94	            }
 95	
 96	            Reservation res = new Reservation();
 97	            res.setRoomNumber(roomNumber);
 98	            res.setGuestName(guestName);
 99	            res.setGuestEmail(guestEmail);
100	            res.setGuestCpf(guestCpf);
101	            res.setCheckIn(checkIn);
102	            res.setCheckOut(checkOut);
103	            res.setGuests(guests);
104	            res.setRatePlan(ratePlanType);
105	            res.setCompanyCode(companyCode);
106	            res.setNights(nights);
107	            res.setSubtotal(pricing.subtotal());
108	            res.setDiscount(pricing.discount());
109	            res.setTotal(pricing.total());
110	            res.setStatus(ReservationStatus.PENDING);
111	            res.setAmountPaid(0.0);
112	
113	            Long id = db.createReservation(res);
114	            res.setId(id);
115	
116	            return Result.success(res);
117	        } catch (SQLException e) {
118	            return Result.error("DATABASE_ERROR", e.getMessage());
119	        }
120	    }
121	
122	    public Result<Reservation> getReservation(Long id) {
123	        try {
124	            Reservation res = db.getReservationById(id);
125	            if (res == null) {
126	                return Result.error("RESERVATION_NOT_FOUND", "Reserva não encontrada");
127	            }
128	            return Result.success(res);
129	        } catch (SQLException e) {
130	            return Result.error("DATABASE_ERROR", e.getMessage());
131	        }
132	    }
133	
134	    public Result<Reservation> confirmReservation(Long id, double amountPaid) {
135	        try {
136	            Reservation res = db.getReservationById(id);
137	            if (res == null) {
138	                return Result.error("RESERVATION_NOT_FOUND", "Reserva não encontrada");
139	            }
140	
141	            if (res.getStatus() != ReservationStatus.PENDING) {
142	                return Result.error("OPERATION_NOT_ALLOWED", "Reserva não está pendente");
143	            }
144	
145	            res.setStatus(ReservationStatus.CONFIRMED);
146	            res.setAmountPaid(Money.round(amountPaid));
147	            db.updateReservation(res);
148	
149	            sendConfirmationEmail(res);
150	
151	            return Result.success(res);
152	        } catch (SQLException e) {
153	            return Result.error("DATABASE_ERROR", e.getMessage());
154	        }
155	    }
156	
157	    public Result<Reservation> checkIn(Long id) {
158	        try {
159	            Reservation res = db.getReservationById(id);
160	            if (res == null) {
161	                return Result.error("RESERVATION_NOT_FOUND", "Reserva não encontrada");
162	            }
163	
164	            if (res.getStatus() != ReservationStatus.CONFIRMED) {
165	                return Result.error("OPERATION_NOT_ALLOWED", "Reserva não está confirmada");
166	            }
167	
168	            res.setStatus(ReservationStatus.CHECKED_IN);
169	            db.updateReservation(res);
170	
171	            return Result.success(res);
172	        } catch (SQLException e) {
173	            return Result.error("DATABASE_ERROR", e.getMessage());
174	        }
175	    }
176	
177	    public Result<Reservation> checkOut(Long id) {
178	        try {
179	            Reservation res = db.getReservationById(id);
180	            if (res == null) {
181	                return Result.error("RESERVATION_NOT_FOUND", "Reserva não encontrada");
182	            }
183	
184	            if (res.getStatus() != ReservationStatus.CHECKED_IN) {
185	                return Result.error("OPERATION_NOT_ALLOWED", "Hóspede não fez check-in");
186	            }
187	
188	            res.setStatus(ReservationStatus.CHECKED_OUT);
189	            db.updateReservation(res);
190	
191	            return Result.success(res);
192	        } catch (SQLException e) {
193	            return Result.error("DATABASE_ERROR", e.getMessage());
194	        }
195	    }
196	
197	    public Result<Reservation> cancelReservation(Long id) {
198	        try {
199	            Reservation res = db.getReservationById(id);
200	            if (res == null) {
201	                return Result.error("RESERVATION_NOT_FOUND", "Reserva não encontrada");
202	            }
203	
204	            if (res.getStatus() != ReservationStatus.PENDING && res.getStatus() != ReservationStatus.CONFIRMED) {
205	                return Result.error("OPERATION_NOT_ALLOWED", "Reserva não pode ser cancelada");
206	            }
207	
208	            res.setStatus(ReservationStatus.CANCELLED);
209	
210	            RatePlan ratePlan = RatePlanFactory.create(res.getRatePlan());
211	            double refundPercentage = ratePlan.getRefundPercentage();
212	            double refundAmount = Money.round(res.getAmountPaid() * (refundPercentage / 100.0));
213	            res.setRefund(refundAmount);
214	
215	            db.updateReservation(res);
216	
217	            return Result.success(res);
218	        } catch (SQLException e) {
219	            return Result.error("DATABASE_ERROR", e.getMessage());
220	        }
221	    }
222	
223	    private void sendConfirmationEmail(Reservation res) throws SQLException {
224	        Room room = db.getRoomByNumber(res.getRoomNumber());
225	        String receipt = generateReceipt(res, room);
226	
227	        String body = "Olá, " + res.getGuestName() + "!\n\n" +
228	                "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
229	                receipt + "\n\n" +
230	                "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
231	                "Até breve!";
232	
233	        Message msg = new Message("EMAIL", res.getGuestEmail(),
234	                "Reserva confirmada - Pousada Maré Alta", body);
235	
236	        db.saveMessage(msg);
237	    }
238	
239	    public String generateReceipt(Reservation res, Room room) {
240	        StringBuilder sb = new StringBuilder();
241	        sb.append("Comprovante de reserva nº ").append(res.getId()).append("\n");
242	        sb.append("Hóspede: ").append(res.getGuestName()).append(" (CPF ").append(res.getGuestCpf()).append(")\n");
243	        sb.append("Quarto: ").append(res.getRoomNumber()).append(" (").append(room.getType().getDisplayName()).append(")\n");
244	
245	        String checkInStr = DateUtils.formatBr(res.getCheckIn());
246	        String checkOutStr = DateUtils.formatBr(res.getCheckOut());
247	        String nightsStr = res.getNights() == 1 ? "1 diária" : res.getNights() + " diárias";
248	        sb.append("Entrada: ").append(checkInStr).append(" | Saída: ").append(checkOutStr).append(" | ").append(nightsStr).append("\n");
249	        sb.append("Diárias: ").append(Money.formatBr(res.getSubtotal())).append("\n");
250	
251	        if (res.getDiscount() > 0) {
252	            sb.append("Desconto: ").append(Money.formatBr(res.getDiscount())).append("\n");
253	        }
254	
255	        sb.append("Total: ").append(Money.formatBr(res.getTotal()));
256	
257	        return sb.toString();
258	    }
259	
260	    public List<Room> getAllRooms() throws SQLException {
261	        return db.getAllRooms();
262	    }
263	
264	    public List<Message> getAllMessages() throws SQLException {
265	        return db.getAllMessages();
266	    }
267	
268	    public String getOccupancyReport(LocalDate date) throws SQLException {
269	        List<Reservation> reservations = db.getReservationsForOccupancy(date);
270	        List<Room> allRooms = db.getAllRooms();
271	
272	        StringBuilder csv = new StringBuilder();
273	        csv.append("room,type,reservation,check_in,check_out\n");
274	
275	        Set<Integer> occupiedRooms = new HashSet<>();
276	        for (Reservation res : reservations) {
277	            occupiedRooms.add(res.getRoomNumber());
278	            Room room = db.getRoomByNumber(res.getRoomNumber());
279	            csv.append(res.getRoomNumber()).append(",")
280	                    .append(room.getType().getDisplayName()).append(",")
281	                    .append(res.getId()).append(",")
282	                    .append(DateUtils.format(res.getCheckIn())).append(",")
283	                    .append(DateUtils.format(res.getCheckOut())).append("\n");
284	        }
285	
286	        csv.append("total,").append(occupiedRooms.size()).append("/").append(allRooms.size());
287	
288	        return csv.toString();
289	    }
290	
291	    public String getRevenueReport(String monthStr) throws SQLException {
292	        var month = DateUtils.parseYearMonth(monthStr);
293	        if (month == null) {
294	            return null;
295	        }
296	
297	        List<Reservation> reservations = db.getReservationsForRevenue(month);
298	
299	        StringBuilder csv = new StringBuilder();
300	        csv.append("reservation,room,check_in,check_out,status,amount\n");
301	
302	        double totalAmount = 0.0;
303	        for (Reservation res : reservations) {
304	            double amount = res.getAmountPaid();
305	            if (res.getRefund() != null) {
306	                amount -= res.getRefund();
307	            }
308	
309	            csv.append(res.getId()).append(",")
310	                    .append(res.getRoomNumber()).append(",")
311	                    .append(DateUtils.format(res.getCheckIn())).append(",")
312	                    .append(DateUtils.format(res.getCheckOut())).append(",")
313	                    .append(res.getStatus()).append(",")
314	                    .append(Money.format(amount)).append("\n");
315	
316	            totalAmount = Money.round(totalAmount + amount);
317	        }
318	
319	        csv.append("total,,,,").append(Money.format(totalAmount));
320	
321	        return csv.toString();
322	    }
323	
324	    public static class Result<T> {
325	        private final T data;
326	        private final String errorCode;
327	        private final String errorMessage;
328	        private final boolean success;
329	
330	        private Result(T data, String errorCode, String errorMessage) {
331	            this.data = data;
332	            this.errorCode = errorCode;
333	            this.errorMessage = errorMessage;
334	            this.success = errorCode == null;
335	        }
336	
337	        public static <T> Result<T> success(T data) {
338	            return new Result<>(data, null, null);
339	        }
340	
341	        public static <T> Result<T> error(String code, String message) {
342	            return new Result<>(null, code, message);
343	        }
344	
345	        public boolean isSuccess() {
346	            return success;
347	        }
348	
349	        public T getData() {
350	            return data;
351	        }
352	
353	        public String getErrorCode() {
354	            return errorCode;
355	        }
356	
357	        public String getErrorMessage() {
358	            return errorMessage;
359	        }
360	    }
361	}

