248	        sb.append("Entrada: ").append(checkInStr).append(" | Saída: ").append(checkOutStr).append(" | ").append(nightsStr).append("\n");
249	        sb.append("Diárias: ").append(Money.formatBr(res.getSubtotal())).append("\n");
250	
251	        if (res.getDiscount() > 0) {
252	            sb.append("Desconto: ").append(Money.formatBr(res.getDiscount())).append("\n");
253	        }
254	
255	        sb.append("Total: ").append(Money.formatBr(res.getTotal()));
256	
257	        return sb.toString();
258	    }
