 74	    private void createReservation(io.javalin.http.Context ctx) {
 75	        try {
 76	            JsonObject body = JsonParser.parseString(ctx.body()).getAsJsonObject();
 77	
 78	            Integer roomNumber = getInt(body, "roomNumber");
 79	            String guestName = getString(body, "guestName");
