 84	            Integer guests = getInt(body, "guests");
 85	            String ratePlanStr = getString(body, "ratePlan");
 86	            String companyCode = getString(body, "companyCode");
 87	
 88	            if (roomNumber == null || guestName == null || guestEmail == null || guestCpf == null ||
 89	                    checkInStr == null || checkOutStr == null || guests == null || ratePlanStr == null) {
 90	                ctx.status(400).json(error("INVALID_REQUEST", "Campo obrigatório faltando"));
 91	                return;
 92	            }
 93	
 94	            LocalDate checkIn = DateUtils.parse(checkInStr);
