 97	
 98	            if (checkIn == null || checkOut == null || ratePlan == null) {
 99	                ctx.status(400).json(error("INVALID_REQUEST", "Dados inválidos"));
100	                return;
101	            }
102	
103	            var result = service.createReservation(roomNumber, guestName, guestEmail, guestCpf,
104	                    checkIn, checkOut, guests, ratePlan, companyCode);
105	
106	            if (!result.isSuccess()) {
107	                int statusCode = switch (result.getErrorCode()) {
