     9	public class CorporateRatePlan implements RatePlan {
    10	    private static final Map<String, Double> COMPANY_DISCOUNTS = Map.of(
    11	            "TECNOSUL", 0.12,
    12	            "AGROVALE", 0.18,
    13	            "FARMAVIDA", 0.25
    14	    );
    15	
    16	    @Override
    17	    public ValidationError validate(LocalDate checkIn, LocalDate checkOut, int guests, Room room, String companyCode) {
    18	        if (companyCode == null || companyCode.isBlank()) {
    19	            return ValidationError.invalid("INVALID_REQUEST", "Código de empresa é obrigatório");
    20	        }
    21	
    22	        if (!COMPANY_DISCOUNTS.containsKey(companyCode.toUpperCase())) {
    23	            return ValidationError.invalid("INVALID_REQUEST", "Código de empresa inválido");
    24	        }
    25	
    26	        if (guests < 1) {
    27	            return ValidationError.invalid("INVALID_REQUEST", "Mínimo de 1 hóspede");
    28	        }
    29	        if (guests > room.getCapacity()) {
    30	            return ValidationError.invalid("CAPACITY_EXCEEDED", "Número de hóspedes excede a capacidade");
    31	        }
    32	        if (!checkOut.isAfter(checkIn)) {
    33	            return ValidationError.invalid("INVALID_REQUEST", "Check-out deve ser depois do check-in");
    34	        }
    35	        int nights = DateUtils.nightsBetween(checkIn, checkOut);
    36	        if (nights < 1) {
    37	            return ValidationError.invalid("INVALID_REQUEST", "Mínimo de 1 noite");
    38	        }
    39	        return null;
    40	    }
    41	
    42	    @Override
    43	    public PricingResult calculatePrice(LocalDate checkIn, LocalDate checkOut, Room room) {
    44	        double nightlyRate = room.getNightlyRate();
    45	        int nights = DateUtils.nightsBetween(checkIn, checkOut);
    46	        double subtotal = 0.0;
    47	
    48	        for (int i = 0; i < nights; i++) {
    49	            LocalDate night = checkIn.plusDays(i);
    50	            double nightPrice = nightlyRate;
    51	
    52	            if (DateUtils.isHighSeason(night)) {
    53	                nightPrice = Money.round(nightPrice * 1.20);
    54	            }
    55	
    56	            subtotal = Money.round(subtotal + nightPrice);
    57	        }
    58	
    59	        return new PricingResult(subtotal, 0.0, subtotal);
    60	    }
    61	
    62	    @Override
    63	    public double getRefundPercentage() {
    64	        return 100.0;
    65	    }
