    67	    public PricingResult calculatePriceWithCompany(LocalDate checkIn, LocalDate checkOut, Room room, String companyCode) {
    68	        double nightlyRate = room.getNightlyRate();
    69	        int nights = DateUtils.nightsBetween(checkIn, checkOut);
    70	        double subtotal = 0.0;
    71	
    72	        for (int i = 0; i < nights; i++) {
    73	            LocalDate night = checkIn.plusDays(i);
    74	            double nightPrice = nightlyRate;
    75	
    76	            if (DateUtils.isHighSeason(night)) {
    77	                nightPrice = Money.round(nightPrice * 1.20);
    78	            }
    79	
    80	            subtotal = Money.round(subtotal + nightPrice);
    81	        }
    82	
    83	        double discountPercentage = COMPANY_DISCOUNTS.getOrDefault(companyCode.toUpperCase(), 0.0);
    84	        double discount = Money.round(subtotal * discountPercentage);
    85	        double total = Money.round(subtotal - discount);
    86	
    87	        return new PricingResult(subtotal, discount, total);
    88	    }
