     8	public class StandardRatePlan implements RatePlan {
     9	    @Override
    10	    public ValidationError validate(LocalDate checkIn, LocalDate checkOut, int guests, Room room, String companyCode) {
    11	        if (guests < 1) {
    12	            return ValidationError.invalid("INVALID_REQUEST", "Mínimo de 1 hóspede");
    13	        }
    14	        if (guests > room.getCapacity()) {
    15	            return ValidationError.invalid("CAPACITY_EXCEEDED", "Número de hóspedes excede a capacidade");
    16	        }
    17	        if (!checkOut.isAfter(checkIn)) {
    18	            return ValidationError.invalid("INVALID_REQUEST", "Check-out deve ser depois do check-in");
    19	        }
    20	        int nights = DateUtils.nightsBetween(checkIn, checkOut);
    21	        if (nights < 1) {
    22	            return ValidationError.invalid("INVALID_REQUEST", "Mínimo de 1 noite");
    23	        }
    24	        return null;
    25	    }
    26	
    27	    @Override
    28	    public PricingResult calculatePrice(LocalDate checkIn, LocalDate checkOut, Room room) {
    29	        double nightlyRate = room.getNightlyRate();
    30	        int nights = DateUtils.nightsBetween(checkIn, checkOut);
    31	        double subtotal = 0.0;
    32	
    33	        for (int i = 0; i < nights; i++) {
    34	            LocalDate night = checkIn.plusDays(i);
    35	            double nightPrice = nightlyRate;
    36	
    37	            if (DateUtils.isHighSeason(night)) {
    38	                nightPrice = Money.round(nightPrice * 1.20);
    39	            }
    40	
    41	            subtotal = Money.round(subtotal + nightPrice);
    42	        }
    43	
    44	        double discount = 0.0;
    45	        double total = Money.round(subtotal - discount);
    46	
    47	        return new PricingResult(subtotal, discount, total);
    48	    }
