    29	    }
    30	
    31	    public static YearMonth parseYearMonth(String str) {
    32	        try {
    33	            String[] parts = str.split("-");
    34	            if (parts.length != 2) return null;
    35	            return YearMonth.of(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
    36	        } catch (Exception e) {
