    45	    public static boolean isHighSeason(LocalDate date) {
    46	        int month = date.getMonthValue();
    47	        int day = date.getDayOfMonth();
    48	
    49	        if (month == 7) return true;
    50	        if (month == 12 && day >= 15) return true;
